targets.expr:
(sum by (project_uuid, project_name) (
  oie_instance_info{
    job="openstack-instance-exporter",
    instance=~"^${gvar_oie_hypervisor}(:[0-9]+)?$",
    project_uuid=~"$gvar_oie_project_uuid",
    project_name=~"$gvar_oie_project_name"
  }
))
and on(project_uuid, project_name)
topk(${gvar_oie_top_projects}, ${gvar_oie_rank_projects_by:raw}(((sum by (project_uuid, project_name) (
  oie_instance_info{
    job="openstack-instance-exporter",
    instance=~"^${gvar_oie_hypervisor}(:[0-9]+)?$",
    project_uuid=~"$gvar_oie_project_uuid",
    project_name=~"$gvar_oie_project_name"
  }
)))[${__range_s}s:] @ end()))

